$scriptblockInvokeCheck = {
    param([string[]] $Argument, [DateTimeOffset] $Clock, [string] $Checker, [bool] $RequireLocal)
    # The wrapper preserves actual checker bytes, arguments, native exit and
    # exception text. It is not a literal -File launch of the documented command.
    $arrParameterTokens = @('-ProposedPolicy', '-InputRevision', '-PublishedBaselineRevision',
        '-SelfTest', '-MetadataClassificationOnly', '-FinalizeMetadataNow')
    $strCommandArguments = (@($Argument | ForEach-Object {
                if ($arrParameterTokens -ccontains $_) { $_ } else { "'" + $_.Replace("'", "''") + "'" }
            }) -join ' ')
    $strCommand = '$ErrorActionPreference = ''Stop''; function Invoke-AgentInstructionFixtureClock {' +
        ${function:Invoke-AgentInstructionFixtureClock}.ToString() + '}; $checker = ''' + $Checker.Replace("'", "''") +
        '''; try { Invoke-AgentInstructionFixtureClock -CheckerPath $checker -UtcNow ''' + $Clock.ToString('o') +
        ''' ' + $(if ($RequireLocal) { '-RequireLocal ' } else { '' }) +
        '-Action { & $checker ' + $strCommandArguments +
        ' } } catch { [Console]::Out.WriteLine($_.Exception.Message); exit 1 }'
    $strOutput = (& $strHostPath -NoLogo -NoProfile -NonInteractive -Command $strCommand 2>&1 | Out-String)
    $intExit = $LASTEXITCODE
    if ($strOutput -match 'Fixture clock control failed:|Fixture clock requires one exact') {
        throw "The private caller clock failed: $strOutput"
    }
    [pscustomobject]@{ Output = $strOutput; ExitCode = $intExit }
}

author_transport_prepared:
$scriptblockInvokeCheck = {
    param([string[]] $Argument, [DateTimeOffset] $Clock, [string] $Checker, [bool] $RequireLocal)
    # The wrapper preserves actual checker bytes, arguments, native exit and
    # exception text. It is not a literal -File launch of the documented command.
    $arrParameterTokens = @('-ProposedPolicy', '-InputRevision', '-PublishedBaselineRevision',
        '-SelfTest', '-MetadataClassificationOnly', '-FinalizeMetadataNow')
    $strCommandArguments = (@($Argument | ForEach-Object {
                if ($arrParameterTokens -ccontains $_) { $_ } else { "'" + $_.Replace("'", "''") + "'" }
            }) -join ' ')
    $strCommand = '$ErrorActionPreference = ''Stop''; function Invoke-AgentInstructionFixtureClock {' +
        ${function:Invoke-AgentInstructionFixtureClock}.ToString() + '}; $checker = ''' + $Checker.Replace("'", "''") +
        '''; try { Invoke-AgentInstructionFixtureClock -CheckerPath $checker -UtcNow ''' + $Clock.ToString('o') +
        ''' ' + $(if ($RequireLocal) { '-RequireLocal ' } else { '' }) +
        '-Action { & $checker ' + $strCommandArguments +
        ' } } catch { [Console]::Out.WriteLine($_.Exception.Message); exit 1 }'
    $strCommand = '$global:PS235TimingCall=0L; $global:PS235TimingFailure=$false; $global:PS235ObserverFailure=$false; . /input/observers.ps1; ' + $strCommand + '; if($global:PS235TimingFailure -or $global:PS235ObserverFailure){exit 97}'
    if($script:PairVariant -cnotin @('control','profile')){throw 'Unexpected selected child'}
    $strPairSpec=Join-Path $script:PairOutput ($script:PairVariant+'.spec.json')
    if(Test-Path -LiteralPath $strPairSpec){throw 'Selected child must execute only once'}
    $arrPairOriginal=[IO.File]::ReadAllBytes($Checker)
    if((Get-FileHash -LiteralPath $Checker -Algorithm SHA256).Hash.ToLowerInvariant() -cne $script:PairCatalog.OriginalSha256){throw 'Original fixture checker identity drift'}
    $objPS235AdapterPrimary = $null
    try {
        # The actual dispatcher has already selected B. Change only this private
        # live checker after checkout; both immutable B/H objects stay identical.
        $strSelectedPath=if($script:PairVariant -ceq 'control'){'/input/control.ps1'}else{$script:PairProfile}
        $strSelectedHash=if($script:PairVariant -ceq 'control'){$script:PairCatalog.OriginalSha256}else{$script:PairCatalog.ProfileSha256}
        [IO.File]::WriteAllBytes($Checker,[IO.File]::ReadAllBytes($strSelectedPath))
        if((Get-FileHash -LiteralPath $Checker -Algorithm SHA256).Hash.ToLowerInvariant() -cne $strSelectedHash){throw 'Selected checker identity drift'}
        [ordered]@{variant=$script:PairVariant;command=@($strHostPath,'-NoLogo','-NoProfile','-NonInteractive','-Command',$strCommand);cwd=(Get-Location).Path;timeout_seconds=120;checker_sha256=(Get-FileHash -LiteralPath $Checker -Algorithm SHA256).Hash.ToLowerInvariant();arguments=$Argument;clock=$Clock.ToString('o');require_local=$RequireLocal}|ConvertTo-Json -Depth 6|Set-Content -LiteralPath $strPairSpec -Encoding utf8NoBOM
        & python $script:PairChildRunner --spec $strPairSpec
        $intPairTransportExit=$LASTEXITCODE
        if($intPairTransportExit -ne 0){throw 'Bounded selected-child transport failed'}
        $objPairChild=Get-Content -LiteralPath (Join-Path $script:PairOutput ($script:PairVariant+'-child.json')) -Raw|ConvertFrom-Json
        if($objPairChild.state -cne 'completed'){throw 'Selected child did not complete'}
        $strOutput=[string]$objPairChild.stdout+[string]$objPairChild.stderr
        $intExit=[int]$objPairChild.exit
    } catch {
        $objPS235AdapterPrimary = $_
        throw
    } finally {
        try {
        [IO.File]::WriteAllBytes($Checker,$arrPairOriginal)
        if((Get-FileHash -LiteralPath $Checker -Algorithm SHA256).Hash.ToLowerInvariant() -cne $script:PairCatalog.OriginalSha256){throw 'Private checker restoration failed'}
        } catch { if ($null -eq $objPS235AdapterPrimary) { throw }; [Console]::Error.WriteLine('PS235CLEANUP|' + $_.Exception.Message) }
    }
    if ($strOutput -match 'Fixture clock control failed:|Fixture clock requires one exact') {
        throw "The private caller clock failed: $strOutput"
    }
    [pscustomobject]@{ Output = $strOutput; ExitCode = $intExit }
}
